// Content with portions generated by generative AI platform
package org.eclipse.kura.container.orchestration.provider;

import static org.junit.Assert.assertEquals;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Optional;

import org.eclipse.kura.container.orchestration.provider.impl.enforcement.AllowlistEnforcement;
import org.junit.Test;

public class ContainerDigestRegistrationTest {

    private static final String CONTAINER_ID = "1d3dewf34r5";
    private static final String OTHER_CONTAINER_ID = "9f8e7d6c5b4";
    private static final String DIGEST = "sha256:c26ae7472d624ba1fafd296e73cecc4f93f853088e6a9c13c0d52f6ca5865107";

    private AllowlistEnforcement enforcement;
    private boolean removed;

    @Test
    public void registeredDigestIsListed() {
        givenAllowlistEnforcement();

        whenContainerIsRegistered(CONTAINER_ID, Optional.of(DIGEST));

        thenRegisteredDigestsAre(DIGEST);
    }

    @Test
    public void containerWithoutDigestRegistersNothing() {
        givenAllowlistEnforcement();

        whenContainerIsRegistered(CONTAINER_ID, Optional.empty());

        thenRegisteredDigestsAre();
    }

    @Test
    public void unregisteredDigestIsNoLongerListed() {
        givenAllowlistEnforcement();
        givenRegisteredContainer(CONTAINER_ID, DIGEST);

        whenContainerIsUnregistered(CONTAINER_ID);

        thenRegisteredDigestsAre();
        thenRemovalIsReported(true);
    }

    @Test
    public void unregisteringUnknownContainerChangesNothing() {
        givenAllowlistEnforcement();
        givenRegisteredContainer(CONTAINER_ID, DIGEST);

        whenContainerIsUnregistered(OTHER_CONTAINER_ID);

        thenRegisteredDigestsAre(DIGEST);
        thenRemovalIsReported(false);
    }

    private void givenAllowlistEnforcement() {
        this.enforcement = new AllowlistEnforcement();
    }

    private void givenRegisteredContainer(String containerId, String digest) {
        this.enforcement.register(containerId, Optional.of(digest));
    }

    private void whenContainerIsRegistered(String containerId, Optional<String> digest) {
        this.enforcement.register(containerId, digest);
    }

    private void whenContainerIsUnregistered(String containerId) {
        this.removed = this.enforcement.unregister(containerId);
    }

    private void thenRegisteredDigestsAre(String... expectedDigests) {
        assertEquals(new HashSet<>(Arrays.asList(expectedDigests)), this.enforcement.getRegisteredDigests());
    }

    private void thenRemovalIsReported(boolean expected) {
        assertEquals(expected, this.removed);
    }
}
